61	const WINDOWS = process.platform === "win32";
62	
63	/**
64	 * Kill the whole process tree, not the immediate child. On Windows the child
65	 * pid belongs to the directly spawned harness executable, and `taskkill /t`
66	 * reaches everything under it. `taskkill` runs by full path — the harness
67	 * environment deliberately has no guaranteed PATH (hazard 9's class), and a
68	 * PATH-miss that silently skips the kill is a timeout that never fires. On
69	 * POSIX the child is detached and the negative pid kills its process group.
70	 */
71	export function killTree(pid: number): void {
72	  if (WINDOWS) {
73	    const taskkill = join(process.env.SystemRoot ?? "C:\\WINDOWS", "System32", "taskkill.exe");
74	    const result = spawnSync(taskkill, ["/pid", String(pid), "/t", "/f"], { encoding: "utf8" });
75	    if (result.error) {
76	      throw new Error(`tree-kill failed: ${result.error.message}`);
77	    }
78	  } else {
79	    try {
80	      process.kill(-pid, "SIGKILL");
81	    } catch {
82	      process.kill(pid, "SIGKILL");
83	    }
84	  }
85	}
