87	/**
88	 * Hazard 9: verify the executable resolves in the environment that will
89	 * actually spawn it, and fail closed with a named cause before any real
90	 * invocation is attempted.
91	 */
92	export interface ProbeOptions {
93	  timeoutMs?: number;
94	  env?: Record<string, string>;
95	  cwd?: string;
96	  executablePath?: string;
97	}
98	
99	export interface ProbeResult {
100	  stdout: string;
101	  stderr: string;
102	}
103	
104	export function probeExecutor(executor: ExecutorDefinition, options: ProbeOptions = {}): ProbeResult {
105	  if (options.executablePath !== undefined && !isAbsolute(options.executablePath)) {
106	    throw new Error(`probe failed for executor ${executor.id}: executablePath must be absolute`);
107	  }
108	  const result = spawnSync(options.executablePath ?? executor.probe[0], executor.probe.slice(1), {
109	    shell: false,
110	    encoding: "utf8",
111	    ...(options.timeoutMs === undefined ? {} : { timeout: options.timeoutMs }),
112	    ...(options.env === undefined ? {} : { env: options.env }),
113	    ...(options.cwd === undefined ? {} : { cwd: options.cwd }),
114	  });
115	  if (result.error) {
116	    if (options.timeoutMs !== undefined && (result.error as NodeJS.ErrnoException).code === "ETIMEDOUT") {
117	      throw new Error(`probe failed for executor ${executor.id}: timed out after ${options.timeoutMs} ms (${result.error.message})`);
118	    }
119	    throw new Error(`probe failed for executor ${executor.id}: ${result.error.message}`);
120	  }
121	  if (result.status !== 0) {
122	    const detail = [result.stderr, result.stdout].map((text) => (text ?? "").trim()).filter(Boolean).join("; ");
123	    throw new Error(
124	      `probe failed for executor ${executor.id}: ${executor.probe.join(" ")} exited with code ${result.status}${detail ? `: ${detail}` : ""}`
125	    );
126	  }
127	  return { stdout: result.stdout ?? "", stderr: result.stderr ?? "" };
128	}
