130	export function buildHarnessEnvironment(
131	  executor: ExecutorDefinition,
132	  source: NodeJS.ProcessEnv = process.env,
133	): Record<string, string> {
134	  const env: Record<string, string> = {};
135	  for (const name of executor.sandbox.envPassthrough) {
136	    const value = source[name];
137	    if (value !== undefined) env[name] = value;
138	  }
139	  return env;
140	}
