142	/**
143	 * Parse the machine-generated outer envelope. Field names come from the one
144	 * recorded real invocation (hard rule 5), not from documentation memory.
145	 * The effective model is the unique `modelUsage` entry whose input tokens
146	 * match the top-level `usage.input_tokens`: the recorded envelope shows
147	 * auxiliary model queries (a title generation) alongside the real turn, and
148	 * only the effective model's usage lands in the top-level `usage`. Anything
149	 * the envelope omits stays `null`, never zero.
150	 */
151	export function parseEnvelope(executor: ExecutorDefinition, raw: string): HarnessEnvelope {
152	  let parsed: EnvelopeShape;
153	  try {
154	    parsed = JSON.parse(raw) as EnvelopeShape;
155	  } catch (err) {
156	    throw new Error(`harness envelope for executor ${executor.id} is not valid JSON: ${(err as Error).message}`);
157	  }
158	  const usage = parsed.usage ?? {};
159	  const matches = Object.entries(parsed.modelUsage ?? {}).filter(([, u]) => u.inputTokens === usage.input_tokens);
160	  return {
161	    effectiveModel: matches.length === 1 ? matches[0][0] : null,
162	    fallback: null,
163	    tokensIn: usage.input_tokens ?? null,
164	    tokensOut: usage.output_tokens ?? null,
165	    cacheRead: usage.cache_read_input_tokens ?? null,
166	    cacheWrite: usage.cache_creation_input_tokens ?? null,
167	    cost: parsed.total_cost_usd ?? null,
168	    resultText: parsed.result ?? "",
169	  };
170	}
