export interface HarnessEnvelope {
  effectiveModel: string | null;
  fallback: string | null;
  tokensIn: number | null;
  tokensOut: number | null;
  cacheRead: number | null;
  cacheWrite: number | null;
  cost: number | null;
  resultText: string;
